import { FormEvent, useState } from 'react';

import queryString from 'query-string';
import { useLocation } from 'react-router-dom';

import { userPasswordRecovery } from '@apps/Users/@services/user.services';
import PageLoader from '@components/PageLoader';
import notificationHelper, { error } from '@helpers/notificationHelper';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohInput from '@ui-kit/Input';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';

function Recovery() {
  const location = useLocation();
  const search = queryString.parse(location.search) || {};
  const defaultLogin = (search?.login as string) || '';
  const redirectTo = search.return || search.rel || '/';

  const [login, setLogin] = useState(defaultLogin);
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<any>(null);

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault();

    try {
      const result = await userPasswordRecovery({
        loginOrEmail: login,
        redirectTo,
      });
      if (result?.success) {
        setLoading(true);

        setData(result);
      }
    } catch (err) {
      notificationHelper.error((err as Error).message);
      error((err as Error).message || 'Что-то пошло не так');
    }
  };

  return (
    <PohContainer>
      <form onSubmit={handleSubmit}>
        <PohRow>
          <PohCol lg={{ span: 8, offset: 2 }}>
            <PohRow>
              <PohCol lg={{ span: 8, offset: 4 }} sm={{ offset: 4 }}>
                <h2 className="mb-4">Восстановить пароль</h2>
              </PohCol>
            </PohRow>
            {loading && !data && <PageLoader />}
            {!loading && !data && (
              <PohInput
                onChange={setLogin}
                value={login}
                required
                horizontal
                inputGrid={8}
                labelGrid={4}
                label="Логин или email"
                placeholder="Введите логин или email"
              />
            )}
            {data && (
              <PohRow>
                <PohCol lg={{ span: 8, offset: 4 }} sm={{ offset: 4 }}>
                  <p>
                    На вашу почту <strong>{data.email as string}</strong> отправлено письмо с
                    информацией о восстановлении пароля
                  </p>{' '}
                </PohCol>
              </PohRow>
            )}
            {!data && (
              <PohRow className="mt-4">
                <PohCol lg={{ span: 8, offset: 4 }} sm={{ offset: 4 }}>
                  <PohButton disabled={loading} type="submit" variant={ButtonVariant.Primary}>
                    Восстановить пароль
                  </PohButton>
                </PohCol>
              </PohRow>
            )}
          </PohCol>
        </PohRow>
      </form>
    </PohContainer>
  );
}

export default Recovery;
